@pytest.mark.asyncio

async def test_anthropic_tool_calling() -> None:
    """Chat request to Anthropic provider with a tool definition; assistant responds with a tool call."""
    client = create_client(api_key="test-key", base_url=os.environ["MOCK_SERVER_URL"] + "/fixtures/anthropic_tool_calling")
    req = ChatCompletionRequest.from_json("{\"max_tokens\":256,\"messages\":[{\"content\":\"What is the weather in London?\",\"role\":\"user\"}],\"model\":\"anthropic/claude-3-5-sonnet-20241022\",\"tool_choice\":\"auto\",\"tools\":[{\"function\":{\"description\":\"Get the current weather for a given location\",\"name\":\"get_weather\",\"parameters\":{\"properties\":{\"location\":{\"description\":\"The city and country, e.g. London, UK\",\"type\":\"string\"},\"unit\":{\"description\":\"The temperature unit to use\",\"enum\":[\"celsius\",\"fahrenheit\"],\"type\":\"string\"}},\"required\":[\"location\"],\"type\":\"object\"}},\"type\":\"function\"}]}")

    result = await client.chat(req)
    assert len(result.choices) == 1
    assert result.choices[0].message.tool_calls is not None and (not hasattr(result.choices[0].message.tool_calls, "__len__") or len(result.choices[0].message.tool_calls) > 0)
    assert _alef_e2e_text(result.choices[0].message.tool_calls[0].function.name if result.choices[0].message.tool_calls else None).lower() == "get_weather".lower()
    assert _alef_e2e_text(result.choices[0].finish_reason).lower() == "tool_calls".lower()


